const D = { energy:.55, density:.5, scale:1, speed:1, alpha:.5, hue:200, x:.5, y:.2, style:'film', act:'drain', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lrp=(a,b,t)=>a+(b-a)*t;
const md=(a,n)=>((a%n)+n)%n;
const frc=v=>v-Math.floor(v);
const pp=v=>{const x=Math.abs(v)%2;return x>1?2-x:x;};
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2=(h,s,v)=>{h=md(h,360)/60;s=clp(s,0,1);v=clp(v,0,1);const c=v*s,x=c*(1-Math.abs(h%2-1)),m=v-c;let r=0,g2=0,b=0;
  if(h<1){r=c;g2=x;}else if(h<2){r=x;g2=c;}else if(h<3){g2=c;b=x;}else if(h<4){g2=x;b=c;}else if(h<5){r=x;b=c;}else{r=c;b=x;}
  return [(r+m)*255,(g2+m)*255,(b+m)*255];};
const rgb2h=(r,g,b)=>{const mx=Math.max(r,g,b),mn=Math.min(r,g,b),d2=mx-mn;let h=0;
  if(d2>1e-6){ if(mx===r)h=60*(((g-b)/d2)%6); else if(mx===g)h=60*((b-r)/d2+2); else h=60*((r-g)/d2+4); }
  return [md(h,360), mx<1e-6?0:d2/mx, mx];};

const W=width, Hh=height, u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style, act=P.act||'drain';
const isBub=st==='bubble', isBand=st==='banded', isMono=st==='mono';
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const en=clp(P.energy,0,1), dn=clp(P.density,0,1), al=clp(P.alpha,0,1);
const sp=P.speed, sc=clp(P.scale,0.25,2.4);
const NL=768, DMAX=1750; // nm of optical path — ~5 fringe orders across the LUT

// ---- thin-film interference LUT: I(lambda) = sin^2(2*pi*n*d/lambda), hue-rotated ----
const lkey=md(Math.round(H),360)+'|'+st;
if(!S.lut||S.lkey!==lkey){
  const lut=new Uint8Array(NL*3), n2=1.33, rot=H-200;
  for(let i=0;i<NL;i++){
    const d2=i/NL*DMAX;
    let r,g2,b;
    if(isMono){ const I=Math.pow(Math.sin(6.283*n2*d2/589),2); const c=hsb2(H,0.86,I); r=c[0]/255; g2=c[1]/255; b=c[2]/255; }
    else{
      r=Math.pow(Math.sin(6.283*n2*d2/620),2); g2=Math.pow(Math.sin(6.283*n2*d2/540),2); b=Math.pow(Math.sin(6.283*n2*d2/460),2);
      const hs=rgb2h(r,g2,b); const c=hsb2(hs[0]+rot,hs[1],hs[2]); r=c[0]/255; g2=c[1]/255; b=c[2]/255;
    }
    lut[i*3]=clp(r,0,1)*255; lut[i*3+1]=clp(g2,0,1)*255; lut[i*3+2]=clp(b,0,1)*255;
  }
  S.lut=lut; S.lkey=lkey;
}

// ---- drain / pop / reform cycle (period ~47s — nowhere near the 8s motion gate) ----
let cy, envT=1;
if(act==='hold'){ cy=0.30+0.16*Math.sin(K.t*0.043*sp); }
else if(act==='breathe'){ cy=clp(0.16+0.62*(1-K.intensity)+0.10*Math.sin(K.t*0.11*sp),0,0.9); envT=1+0.7*K.swell; }
else { cy=frc(K.t/(47/Math.max(0.1,sp))+fr(3)); }
const popS=0.90, popping=(act==='drain'&&cy>popS)?(cy-popS)/(1-popS):0;
const thick=lrp(1.55,0.10,Math.pow(clp(cy/popS,0,1),0.8))*(0.35+1.25*dn); // film thins as it drains
const ax=P.x, ay=P.y;

// ---- field -> buffer (coarse; image()-upscaled — the "shader" trick) ----
const bw=144, bh=Math.max(60,Math.round(144*Hh/W));
if(!S.f||S.bw!==bw||S.bh!==bh){ S.f=createGraphics(bw,bh); S.f.pixelDensity(1); S.bw=bw; S.bh=bh; }
const g=S.f, px=g.pixels, lut=S.lut;
const T=K.t*sp, p1=fr(11)*6.283, p2=fr(12)*6.283, p3=fr(13)*6.283;
const inv=1/Math.max(0.15,sc), turbA=(0.10+0.52*en)*envT;
g.loadPixels();
for(let yy=0;yy<bh;yy++){
  const vy=yy/bh;
  for(let xx=0;xx<bw;xx++){
    const ux=xx/bw;
    // marangoni churn advecting downward + gravity drainage profile
    const s1=Math.sin((ux*8.1+vy*3.3)*inv-T*0.90+p1);
    const s2=Math.sin((ux*4.7-vy*11.3)*inv-T*1.61+p2);
    const s3=Math.sin((ux*17.3+vy*6.1)*inv-T*0.47+p3);
    let d2=thick*(0.22+0.90*Math.pow(vy,1.35))+turbA*(s1*0.5+s2*0.3+s3*0.2)*0.55;
    let mask;
    if(isBub){
      const rr=Math.hypot((ux-ax)*(W/Hh),(vy-ay))/(0.62*sc);
      mask=clp(1-Math.pow(clp(rr,0,1),3.5),0,1)*clp((1-rr)*4.2,0,1);
      d2*=0.35+1.9*Math.pow(clp(rr,0,1),2.0); // fringes bow into the rim where the wall runs oblique
    } else {
      mask=clp(1-Math.pow(Math.abs(ux-0.5)*2,6),0,1)*clp(1-Math.pow(Math.abs(vy-0.5)*2,7),0,1)*0.82+0.18;
    }
    // the black spot: film goes molecularly thin at the drain origin, then ruptures
    const dd=Math.hypot((ux-ax)*(W/Hh),(vy-ay));
    const spot=clp(1-Math.exp(-dd*dd/(0.020+0.10*(1-cy))),0,1);
    d2*=lrp(0.04,1,spot);
    if(popping>0){ const hole=popping*1.75; if(dd<hole) mask*=clp((dd-hole*0.72)/(hole*0.28+1e-3),0,1); }
    const o=4*(yy*bw+xx);
    if(mask<=0.004){ px[o+3]=0; continue; }
    let r,g3,b,ia;
    const li=clp(Math.round(pp(d2)*(NL-1)),0,NL-1)*3;
    if(isBand){
      const q=pp(d2)*5.5, ord=Math.floor(q), fpart=q-ord;
      const li2=clp(Math.round((ord/5.5)*(NL-1)),0,NL-1)*3;
      const edge=(fpart<0.055||fpart>0.945)?0.10:1; // hard contour lines between flat bands
      r=lut[li2]*edge; g3=lut[li2+1]*edge; b=lut[li2+2]*edge;
      ia=mask*(0.42+0.58*en)*255;
    } else {
      r=lut[li]; g3=lut[li+1]; b=lut[li+2];
      const lum=(r+g3+b)/765;
      ia=mask*lrp(0.30,1,lum)*(0.40+0.60*en)*255; // dark fringes contribute nothing — keeps it polite
    }
    px[o]=r; px[o+1]=g3; px[o+2]=b; px[o+3]=ia;
  }
}
g.updatePixels();

// specular reflection sits ON TOP of the scene -> additive, capped well under a blowout
const sm=drawingContext.imageSmoothingEnabled;
if(isBand) drawingContext.imageSmoothingEnabled=false;
blendMode(ADD);
tint(0,0,100, clp(al*38*(1+A.rms*0.35+K.pulse*0.06),0,38));
image(S.f,0,0,W,Hh);
noTint();
blendMode(BLEND);
drawingContext.imageSmoothingEnabled=sm;

// bright specular cap where the bubble wall faces the light
if(isBub&&popping<=0){
  blendMode(ADD); noStroke();
  const gx=(ax-0.13)*W, gy=(ay-0.16)*Hh, gr2=u*0.10*sc*(0.8+0.3*K.swell);
  const gc=hsb2(md(H+30,360),0.10,1);
  const rg=drawingContext.createRadialGradient(gx,gy,0,gx,gy,gr2);
  rg.addColorStop(0,'rgba('+(gc[0]|0)+','+(gc[1]|0)+','+(gc[2]|0)+','+clp(0.30*al*(0.4+en),0,0.34).toFixed(3)+')');
  rg.addColorStop(1,'rgba('+(gc[0]|0)+','+(gc[1]|0)+','+(gc[2]|0)+',0)');
  drawingContext.fillStyle=rg; drawingContext.fillRect(gx-gr2,gy-gr2,gr2*2,gr2*2);
  blendMode(BLEND);
}

blendMode(BLEND); drawingContext.shadowBlur=0; noTint();
